  "regulated_action": {
    "target_id": "t0",
    "description": "Modify the default user address for user_id 'amelia_gonzalez_4098' to '1452 Maple Avenue, Apartment 3B, Denver, CO 80231, USA'"
  },
  "applicable_norms": [
    {
      "policy_source_id": "q7",
      "interpretation": "The assistant can modify the default user address as part of its allowed actions.",
      "modality": "PERMIT"
