    {
      "policy_source_id": "q7",
      "interpretation": "Before taking any action that updates the database, the assistant must list the action details and obtain explicit user confirmation ('yes') to proceed.",
      "modality": "REQUIRE"
    },
    {
      "policy_source_id": "q6",
      "interpretation": "The assistant can only send a message to the user or make a tool call, but not both at the same time.",
      "modality": "REQUIRE"
    }
  ],
